CREATE SCHEMA "projeto";

CREATE TABLE "Participante" (
  "id_participante" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(150) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "nome_usuario" varchar(100) UNIQUE NOT NULL,
  "criado_em" timestamp NOT NULL
);

CREATE TABLE "Projeto" (
  "id_projeto" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(150) UNIQUE NOT NULL,
  "descricao" text,
  "nome_schema" varchar(63) UNIQUE NOT NULL,
  "caminho_raiz" text UNIQUE NOT NULL,
  "criado_em" timestamp NOT NULL,
  "ativo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "ParticipanteProjeto" (
  "id_participante" integer,
  "id_projeto" integer,
  "papel" varchar(30) NOT NULL,
  "associado_em" timestamp NOT NULL,
  PRIMARY KEY ("id_participante", "id_projeto")
);

CREATE TABLE "projeto"."Tarefa" (
  "id_tarefa" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "titulo" varchar(200) NOT NULL,
  "descricao" text,
  "criada_em" timestamp NOT NULL,
  "prazo" timestamp,
  "concluida_em" timestamp,
  "id_responsavel" integer,
  "id_status" integer NOT NULL,
  "id_prioridade" integer NOT NULL,
  "id_categoria" integer,
  "id_checkpoint" integer
);

CREATE TABLE "projeto"."Status" (
  "id_status" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(50) UNIQUE NOT NULL,
  "descricao" text
);

CREATE TABLE "projeto"."Prioridade" (
  "id_prioridade" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(50) UNIQUE NOT NULL,
  "nivel" integer NOT NULL
);

CREATE TABLE "projeto"."Categoria" (
  "id_categoria" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(100) UNIQUE NOT NULL,
  "descricao" text
);

CREATE TABLE "projeto"."Checkpoint" (
  "id_checkpoint" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(150) NOT NULL,
  "descricao" text,
  "data_inicio" timestamp,
  "data_fim" timestamp
);

CREATE TABLE "projeto"."Label" (
  "id_label" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(100) UNIQUE NOT NULL,
  "cor" varchar(20)
);

CREATE TABLE "projeto"."Comentario" (
  "id_comentario" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "texto" text NOT NULL,
  "criado_em" timestamp NOT NULL,
  "id_tarefa" integer NOT NULL,
  "id_autor" integer NOT NULL
);

CREATE TABLE "projeto"."Embedding" (
  "id_embedding" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_tarefa" integer UNIQUE NOT NULL,
  "vetor" vector NOT NULL,
  "modelo" varchar(100) NOT NULL,
  "gerado_em" timestamp NOT NULL
);

CREATE TABLE "projeto"."DependenciaTarefa" (
  "id_tarefa_bloqueada" integer,
  "id_tarefa_bloqueadora" integer,
  "criada_em" timestamp NOT NULL,
  PRIMARY KEY ("id_tarefa_bloqueada", "id_tarefa_bloqueadora")
);

CREATE TABLE "projeto"."TarefaLabel" (
  "id_tarefa" integer,
  "id_label" integer,
  "associada_em" timestamp NOT NULL,
  PRIMARY KEY ("id_tarefa", "id_label")
);

ALTER TABLE "ParticipanteProjeto" ADD FOREIGN KEY ("id_participante") REFERENCES "Participante" ("id_participante") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ParticipanteProjeto" ADD FOREIGN KEY ("id_projeto") REFERENCES "Projeto" ("id_projeto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Tarefa" ADD FOREIGN KEY ("id_responsavel") REFERENCES "Participante" ("id_participante") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Tarefa" ADD FOREIGN KEY ("id_status") REFERENCES "projeto"."Status" ("id_status") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Tarefa" ADD FOREIGN KEY ("id_prioridade") REFERENCES "projeto"."Prioridade" ("id_prioridade") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Tarefa" ADD FOREIGN KEY ("id_categoria") REFERENCES "projeto"."Categoria" ("id_categoria") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Tarefa" ADD FOREIGN KEY ("id_checkpoint") REFERENCES "projeto"."Checkpoint" ("id_checkpoint") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Comentario" ADD FOREIGN KEY ("id_tarefa") REFERENCES "projeto"."Tarefa" ("id_tarefa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Comentario" ADD FOREIGN KEY ("id_autor") REFERENCES "Participante" ("id_participante") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."Embedding" ADD FOREIGN KEY ("id_tarefa") REFERENCES "projeto"."Tarefa" ("id_tarefa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."DependenciaTarefa" ADD FOREIGN KEY ("id_tarefa_bloqueada") REFERENCES "projeto"."Tarefa" ("id_tarefa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."DependenciaTarefa" ADD FOREIGN KEY ("id_tarefa_bloqueadora") REFERENCES "projeto"."Tarefa" ("id_tarefa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."TarefaLabel" ADD FOREIGN KEY ("id_tarefa") REFERENCES "projeto"."Tarefa" ("id_tarefa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projeto"."TarefaLabel" ADD FOREIGN KEY ("id_label") REFERENCES "projeto"."Label" ("id_label") DEFERRABLE INITIALLY IMMEDIATE;
